"""The co-guard Claude Code plugin, generated by the server.

``ensure_plugin(root)`` makes ``root`` (``workspaces/_system/co-guard``) a
read-only plugin directory::

    .claude-plugin/plugin.json
    hooks/hooks.json      every event -> "<server python> -I .../co_hook.py <Event>"
    hooks/co_hook.py
    lib/rules.py, lib/shell.py, lib/dbrules.py
    lib/__pycache__/{rules,shell,dbrules}.<cache tag>.pyc   checked hash-based pycs

``root`` is a symlink to a content-addressed sibling ``.co-guard-<hash>``: when
the content (including the interpreter path) changes, the new version is
written to a temp dir, made read-only (files 0444, dirs 0555), renamed into
place and the symlink is swapped atomically (``os.replace``). Same content ->
nothing is written. Older versions are removed. Called at server startup.

hooks.json follows the format proven on CLI 2.1.329 (spikes doc): string
commands with ``"${CLAUDE_PLUGIN_ROOT}"`` (exec-form arrays were not proven).
"""

from __future__ import annotations

import fcntl
import hashlib
import importlib.util
import json
import os
import shlex
import shutil
import stat
import sys
import threading
import uuid
from importlib._bootstrap_external import _code_to_hash_pyc
from pathlib import Path

from . import co_hook

NAME = "co-guard"
_SRC = Path(__file__).resolve().parent
_FILE_MODE = 0o444
_DIR_MODE = 0o555
_OTHER_TIMEOUT = 15  # spool-only events
_LOCK = threading.Lock()
LIB_MODULES = ("rules", "shell", "dbrules")  # the guard library (stdlib only, Ruling R1)


def _interpreter() -> str:
    exe = sys.executable
    if not exe or not os.path.isabs(exe) or not os.path.isfile(exe):
        raise RuntimeError(f"co-guard: the server's Python ({exe!r}) is not an absolute path to a file")
    return exe


def _command(event: str) -> str:
    # -I: isolated (no env vars, no script dir on sys.path); -S: no site (.pth files never run)
    return f'{shlex.quote(_interpreter())} -I -S "${{CLAUDE_PLUGIN_ROOT}}/hooks/co_hook.py" {event}'


def hooks_json() -> dict:
    def entry(event, timeout, matcher=None):
        e = {"hooks": [{"type": "command", "command": _command(event), "timeout": timeout}]}
        if matcher:
            e = {"matcher": matcher, **e}
        return [e]

    hooks = {
        "PreToolUse": entry("PreToolUse", co_hook.HOOK_TIMEOUT, co_hook.TOOL_MATCHER),
        "PostToolUse": entry("PostToolUse", _OTHER_TIMEOUT, co_hook.TOOL_MATCHER),
    }
    for ev in ("SessionStart", "Stop", "SessionEnd", "SubagentStart", "SubagentStop"):
        hooks[ev] = entry(ev, _OTHER_TIMEOUT)
    # Ruling R19b (unverified): exit 2 blocks a settings change that switches our hooks off
    hooks["ConfigChange"] = entry("ConfigChange", _OTHER_TIMEOUT, co_hook.CONFIG_MATCHER)
    return {"hooks": hooks}


def _pyc(name: str, source: bytes) -> bytes:
    """``lib/<name>.py`` compiled for the server's interpreter (the hook's) as a
    CHECKED hash-based pyc (PEP 552): valid only while the source hash
    matches, independent of file mtimes, byte-identical for the same source -
    the hook never compiles the guard library (the dir is read-only, so it
    could not cache it either)."""
    code = compile(source, f"{name}.py", "exec", dont_inherit=True)
    return _code_to_hash_pyc(code, importlib.util.source_hash(source), True)


def plugin_files() -> dict[str, bytes]:
    manifest = {"name": NAME, "version": "1.0.0",
                "description": "Claude Orchestrator guard: blocks dangerous actions, asks a person for approval."}
    files = {
        ".claude-plugin/plugin.json": (json.dumps(manifest, indent=2) + "\n").encode(),
        "hooks/hooks.json": (json.dumps(hooks_json(), indent=2) + "\n").encode(),
        "hooks/co_hook.py": (_SRC / "co_hook.py").read_bytes(),
    }
    tag = sys.implementation.cache_tag
    for name in LIB_MODULES:
        src = (_SRC / f"{name}.py").read_bytes()
        files[f"lib/{name}.py"] = src
        if tag:
            files[f"lib/__pycache__/{name}.{tag}.pyc"] = _pyc(name, src)
    return files


def content_hash(files: dict[str, bytes]) -> str:
    h = hashlib.sha256()
    for rel in sorted(files):
        h.update(rel.encode() + b"\0" + hashlib.sha256(files[rel]).digest())
    return h.hexdigest()


def _rmtree(path: Path) -> None:
    """Remove a read-only tree (dirs are 0555)."""
    if path.is_symlink() or path.is_file():
        path.unlink(missing_ok=True)
        return
    if not path.exists():
        return
    for d, _dirs, _files in os.walk(path):
        try:
            os.chmod(d, stat.S_IRWXU)
        except OSError:
            pass
    shutil.rmtree(path, ignore_errors=True)


def _write_tree(dest: Path, files: dict[str, bytes]) -> None:
    for rel, data in files.items():
        p = dest / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        os.chmod(p, _FILE_MODE)
    for d, _dirs, _files in os.walk(dest, topdown=False):
        if Path(d) != dest:  # the top dir is made read-only after its rename
            os.chmod(d, _DIR_MODE)


def _matches(version_dir: Path, files: dict[str, bytes]) -> bool:
    """Exactly ``files`` (no extra entries, no symlinks), files 0444, dirs 0555."""
    want_dirs = {str(Path(rel).parent) for rel in files} - {"."}
    want_dirs |= {str(p) for d in list(want_dirs) for p in Path(d).parents if str(p) != "."}
    try:
        if version_dir.is_symlink() or not version_dir.is_dir():
            return False
        seen_files, seen_dirs = set(), set()
        for d, dirs, names in os.walk(version_dir):
            for n in dirs:
                p = Path(d) / n
                rel = str(p.relative_to(version_dir))
                if p.is_symlink() or stat.S_IMODE(p.lstat().st_mode) != _DIR_MODE:
                    return False
                seen_dirs.add(rel)
            for n in names:
                p = Path(d) / n
                rel = str(p.relative_to(version_dir))
                if p.is_symlink() or rel not in files or stat.S_IMODE(p.lstat().st_mode) != _FILE_MODE \
                        or p.read_bytes() != files[rel]:
                    return False
                seen_files.add(rel)
        return (seen_files == set(files) and seen_dirs == want_dirs
                and stat.S_IMODE(version_dir.stat().st_mode) == _DIR_MODE)
    except OSError:
        return False


def ensure_plugin(root: Path, prune: bool = True) -> Path:
    """Make ``root`` the current co-guard plugin; return ``root``. Idempotent and
    cheap when nothing changed; safe to call per task (thread + file lock).
    ``prune`` removes other versions: only at server startup, when no task can
    still be running one (the worker passes ``prune=False``)."""
    root = Path(root).absolute()
    parent = root.parent
    parent.mkdir(parents=True, exist_ok=True)
    with _LOCK:
        fd = os.open(parent / f".{root.name}.lock", os.O_RDWR | os.O_CREAT, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            return _ensure(root, parent, prune)
        finally:
            os.close(fd)


def _ensure(root: Path, parent: Path, prune: bool) -> Path:
    files = plugin_files()
    digest = content_hash(files)[:20]
    version = parent / f".{root.name}-{digest}"

    if not _matches(version, files):
        _rmtree(version)
        tmp = parent / f".{root.name}-tmp-{uuid.uuid4().hex}"
        _write_tree(tmp, files)
        os.rename(tmp, version)  # (renaming a dir needs it writable on macOS)
        os.chmod(version, _DIR_MODE)

    current = os.readlink(root) if root.is_symlink() else None
    if current != version.name:
        if root.exists() and not root.is_symlink():  # a real dir from an older layout
            _rmtree(root)
        link = parent / f".{root.name}-link-{uuid.uuid4().hex}"
        os.symlink(version.name, link)
        os.replace(link, root)

    for old in parent.glob(f".{root.name}-*"):
        if old != version and (prune or "-tmp-" in old.name or "-link-" in old.name):
            _rmtree(old)
    if not _matches(root.resolve(), files):
        raise RuntimeError("co-guard: the plugin could not be installed read-only")
    return root
